```tsx
import { useId } from "react";
import type { ReactElement } from "react";
import "./SettingsToggleRow.css";

export interface SettingsToggleRowProps {
  label: string;
  hint: string;
  checked: boolean;
  onChange: (checked: boolean) => void;
}

export function SettingsToggleRow({
  label,
  hint,
  checked,
  onChange,
}: SettingsToggleRowProps): ReactElement {
  const id = useId();
  const labelId = `${id}-label`;
  const hintId = `${id}-hint`;

  return (
    <div className="settings-toggle-row">
      <div className="settings-toggle-row__text">
        <span id={labelId} className="settings-toggle-row__label">
          {label}
        </span>
        <span id={hintId} className="settings-toggle-row__hint">
          {hint}
        </span>
      </div>
      <button
        type="button"
        className="settings-toggle-row__switch"
        aria-pressed={checked}
        aria-labelledby={labelId}
        aria-describedby={hintId}
        onClick={() => onChange(!checked)}
      >
        <span className="settings-toggle-row__knob" aria-hidden="true" />
      </button>
    </div>
  );
}
```

```css
.settings-toggle-row {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 1rem;
  padding-block: clamp(0.75rem, 1.2vw, 1rem);
  border-bottom: 1px solid var(--hair);
}

.settings-toggle-row__text {
  display: flex;
  flex-direction: column;
  gap: 0.25rem;
  min-width: 0;
}

.settings-toggle-row__label {
  color: var(--ink);
  font-size: clamp(0.95rem, 0.9rem + 0.25vw, 1.1rem);
}

.settings-toggle-row__hint {
  color: var(--muted);
  font-size: clamp(0.8rem, 0.76rem + 0.2vw, 0.9rem);
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}

.settings-toggle-row__switch {
  position: relative;
  flex: none;
  box-sizing: border-box;
  width: 2.75rem;
  height: 1.5rem;
  padding: 0;
  border: 2px solid var(--muted);
  border-radius: 999px;
  background: transparent;
  cursor: pointer;
  font: inherit;
  transition: background-color 150ms ease, border-color 150ms ease;
}

.settings-toggle-row__switch[aria-pressed="true"] {
  background: var(--myelin);
  border-color: var(--myelin);
}

.settings-toggle-row__knob {
  position: absolute;
  top: 50%;
  left: 0.125rem;
  width: 1rem;
  height: 1rem;
  border-radius: 999px;
  background: var(--muted);
  transform: translateY(-50%);
  transition: transform 150ms ease, background-color 150ms ease;
}

.settings-toggle-row__switch[aria-pressed="true"] .settings-toggle-row__knob {
  background: var(--slide);
  transform: translate(1.25rem, -50%);
}

:root[data-motion="reduce"] .settings-toggle-row__switch,
:root[data-motion="reduce"] .settings-toggle-row__knob {
  transition: none;
}

@media (prefers-reduced-motion: reduce) {
  .settings-toggle-row__switch,
  .settings-toggle-row__knob {
    transition: none;
  }
}
